        .app-loading-shell,
        .app-loading-shell * {
          box-sizing: border-box;
        }
        .app-loading-shimmer {
          animation: appLoadingShimmer 1.35s ease-in-out infinite;
        }
        .app-loading-card {
          background: #FFFFFF;
          border: 1px solid #E2E8F0;
          border-radius: 14px;
          box-shadow: 0 2px 14px rgba(15,25,35,0.045);
          overflow: hidden;
        }
        .app-loading-orbit {
          animation: appLoadingSpin 0.9s linear infinite;
        }
        @keyframes appLoadingShimmer {
          0% { background-position: 110% 0; }
          100% { background-position: -110% 0; }
        }
        @keyframes appLoadingSpin {
          to { transform: rotate(360deg); }
        }
        @keyframes appLoadingTape {
          from { transform: translateX(0); }
          to { transform: translateX(-50%); }
        }
        @media (max-width: 820px) {
          .app-loading-header {
            height: 58px !important;
            padding: 0 16px !important;
            padding-top: env(safe-area-inset-top) !important;
          }
          .app-loading-nav,
          .app-loading-actions,
          .app-loading-side {
            display: none !important;
          }
          .app-loading-main {
            padding: 16px 14px calc(96px + env(safe-area-inset-bottom)) !important;
          }
          .app-loading-kpis {
            grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
          }
          .app-loading-grid {
            grid-template-columns: 1fr !important;
          }
          .app-loading-chart {
            height: 172px !important;
          }
        }
        @media (max-width: 380px) {
          .app-loading-kpis {
            grid-template-columns: 1fr !important;
          }
        }
        @media (prefers-reduced-motion: reduce) {
          .app-loading-shimmer,
          .app-loading-orbit,
          .app-loading-tape > div {
            animation: none !important;
          }
        }
      "])

